411:             final DataType outputType;
412:             if (surroundingInfo != null) {
413:                 outputType =
414:                         surroundingInfo
415:                                 .inferOutputType(callContext.getDataTypeFactory())
416:                                 .orElse(null);
417:             } else {
418:                 outputType = null;
419:             }
