422:         } catch (ValidationException e) {
423:             throw createInvalidInputException(typeInference, callContext, e);
424:         }
425: 
426:         // infer output type first for better error message
427:         // (logically state types should be inferred first)
428:         final DataType outputType =
429:                 inferOutputType(adaptedCallContext, typeInference.getOutputTypeStrategy());
430: 
431:         final LinkedHashMap<String, StateInfo> stateInfos =
432:                 inferStateInfos(adaptedCallContext, typeInference.getStateTypeStrategies());
