460:     private static AdaptedCallContext inferInputTypes(
461:             TypeInference typeInference,
462:             CallContext callContext,
463:             @Nullable DataType outputType,
464:             boolean throwOnFailure) {
465: 
466:         final AdaptedCallContext castCallContext =
467:                 new AdaptedCallContext(callContext, outputType);
468: 
469:         // Static arguments have the highest priority
470:         final List<StaticArgument> staticArgs = typeInference.getStaticArguments().orElse(null);
471:         if (staticArgs != null) {
472:             final List<DataType> fromStaticArgs =
473:                     IntStream.range(0, staticArgs.size())
474:                             .mapToObj(
475:                                     pos -> {
476:                                         final StaticArgument expectedArg = staticArgs.get(pos);
477:                                         if (expectedArg.is(StaticArgumentTrait.TABLE)) {
478:                                             final TableSemantics semantics =
479:                                                     callContext.getTableSemantics(pos).orElse(null);
480:                                             if (semantics == null) {
481:                                                 if (throwOnFailure) {
482:                                                     throw new ValidationException(
483:                                                             String.format(
484:                                                                     "Invalid argument value. "
485:                                                                             + "Argument '%s' expects a table to be passed.",
486:                                                                     expectedArg.getName()));
487:                                                 }
488:                                                 return null;
489:                                             }
490:                                             return semantics.dataType();
491:                                         }
492:                                         return expectedArg.getDataType().orElse(null);
493:                                     })
494:                             .collect(Collectors.toList());
495:             if (fromStaticArgs.stream().allMatch(Objects::nonNull)) {
496:                 castCallContext.setExpectedArguments(fromStaticArgs);
497:             } else if (throwOnFailure) {
498:                 throw new ValidationException("Invalid input arguments.");
499:             }
500:         }
501: 
502:         // Even if static arguments are defined, the input strategy is always called
503:         // for validation purposes
504:         final List<DataType> inferredDataTypes =
505:                 typeInference
506:                         .getInputTypeStrategy()
507:                         .inferInputTypes(castCallContext, throwOnFailure)
508:                         .orElse(null);
509:         if (inferredDataTypes != null) {
510:             castCallContext.setExpectedArguments(inferredDataTypes);
511:         } else if (throwOnFailure) {
512:             throw new ValidationException("Invalid input arguments.");
513:         }
514: 
515:         return castCallContext;
516:     }
