88:  * This state backend can store very large state that exceeds memory even disk and spills to remote
89:  * storage.
90:  *
91:  * <p>The behavior of the ForSt instances can be parametrized by setting ForSt Options using the
92:  * methods {@link #setForStOptions(ForStOptionsFactory)}.
93:  */
94: @Experimental
95: public class ForStStateBackend extends AbstractManagedMemoryStateBackend
96:         implements ConfigurableStateBackend {
97: 
98:     public static final String PRIMARY_SHORTCUT_CHECKPOINT = "checkpoint-dir";
99: 
100:     private static final long serialVersionUID = 1L;
101: 
102:     private static final Logger LOG = LoggerFactory.getLogger(ForStStateBackend.class);
103: 
104:     private static final double UNDEFINED_OVERLAP_FRACTION_THRESHOLD = -1;
105: 
106:     /** The number of (re)tries for loading the ForSt JNI library. */
107:     private static final int FORST_LIB_LOADING_ATTEMPTS = 3;
108: 
109:     /** Flag whether the native library has been loaded. */
110:     private static boolean forStInitialized = false;
111: 
112:     // ------------------------------------------------------------------------
113: 
114:     // -- configuration values, set in the application / configuration
115: 
116:     /**
117:      * Base paths for ForSt remote directory, as configured. Null if not yet set, in which case the
118:      * configuration values will be used. The configuration will fallback to local directory by
119:      * default. TODO: fallback to checkpoint directory if not configured.
120:      */
121:     @Nullable private Path remoteForStDirectory;
122: 
123:     /**
124:      * Base paths for ForSt directory, as configured. Null if not yet set, in which case the
125:      * configuration values will be used. The configuration defaults to the TaskManager's temp
126:      * directories.
127:      */
128:     @Nullable private File[] localForStDirectories;
129: 
130:     /** The configurable options. */
131:     @Nullable private ReadableConfig configurableOptions;
132: 
133:     /** The options factory to create the ForSt options in the cluster. */
134:     @Nullable private ForStOptionsFactory forStOptionsFactory;
135: 
136:     /** The configuration for memory settings (pool sizes, etc.). */
137:     private final ForStMemoryConfiguration memoryConfiguration;
138: 
139:     /** The default ForSt property-based metrics options. */
140:     private final ForStNativeMetricOptions nativeMetricOptions;
141: 
142:     // -- runtime values, set on TaskManager when initializing / using the backend
143: 
144:     /** Base paths for ForSt directory, as initialized. */
145:     private transient File[] initializedDbBasePaths;
146: 
147:     /** JobID for uniquifying backup paths. */
148:     private transient JobID jobId;
149: 
150:     /** The index of the next directory to be used from {@link #initializedDbBasePaths}. */
151:     private transient int nextDirectory;
152: 
153:     /** Whether we already lazily initialized our local storage directories. */
154:     private transient boolean isInitialized;
155: 
156:     /** Factory for Write Buffer Manager and Block Cache. */
157:     private final ForStMemoryFactory forStMemoryFactory;
158: 
159:     /**
160:      * The configuration for rocksdb priorityQueue state settings (priorityQueue state type, etc.).
161:      */
162:     private final ForStPriorityQueueConfig priorityQueueConfig;
163: 
164:     /**
165:      * The threshold of the overlap fraction between the handle's key-group range and target
166:      * key-group range.
167:      */
168:     private final double overlapFractionThreshold;
169: 
170:     /**
171:      * Whether we use the optimized Ingest/Clip DB method for rescaling RocksDB incremental
172:      * checkpoints.
173:      */
174:     private final TernaryBoolean useIngestDbRestoreMode;
175: 
176:     /**
177:      * Whether to leverage deleteFilesInRange API to clean up useless rocksdb files during
178:      * rescaling.
179:      */
180:     private final TernaryBoolean rescalingUseDeleteFilesInRange;
181: 
182:     /** The recovery claim mode. */
183:     private RecoveryClaimMode recoveryClaimMode = RecoveryClaimMode.DEFAULT;
184: 
185:     private boolean primaryShareWithCheckpoint;
186: 
187:     // ------------------------------------------------------------------------
188: 
189:     /** Creates a new {@code ForStStateBackend} for storing state. */
190:     public ForStStateBackend() {
191:         this.nativeMetricOptions = new ForStNativeMetricOptions();
192:         this.memoryConfiguration = new ForStMemoryConfiguration();
193:         this.priorityQueueConfig = new ForStPriorityQueueConfig();
194:         this.forStMemoryFactory = ForStMemoryFactory.DEFAULT;
195:         this.overlapFractionThreshold = UNDEFINED_OVERLAP_FRACTION_THRESHOLD;
196:         this.useIngestDbRestoreMode = TernaryBoolean.UNDEFINED;
197:         this.rescalingUseDeleteFilesInRange = TernaryBoolean.UNDEFINED;
198:         this.primaryShareWithCheckpoint = false;
199:     }
200: 
201:     /**
202:      * Private constructor that creates a re-configured copy of the state backend.
203:      *
204:      * @param original The state backend to re-configure.
205:      * @param config The configuration.
206:      * @param classLoader The class loader.
207:      */
208:     private ForStStateBackend(
209:             ForStStateBackend original, ReadableConfig config, ClassLoader classLoader) {
210:         this.memoryConfiguration =
211:                 ForStMemoryConfiguration.fromOtherAndConfiguration(
212:                         original.memoryConfiguration, config);
213:         this.memoryConfiguration.validate();
214: 
215:         this.primaryShareWithCheckpoint = false;
216:         if (original.remoteForStDirectory != null) {
217:             this.remoteForStDirectory = original.remoteForStDirectory;
218:         } else {
219:             String remoteDirStr = config.get(ForStOptions.PRIMARY_DIRECTORY);
220:             if (PRIMARY_SHORTCUT_CHECKPOINT.equals(remoteDirStr)) {
221:                 this.remoteForStDirectory = null;
222:                 this.primaryShareWithCheckpoint = true;
223:             } else {
224:                 this.remoteForStDirectory = remoteDirStr == null ? null : new Path(remoteDirStr);
225:             }
226:         }
227: 
228:         this.priorityQueueConfig =
229:                 ForStPriorityQueueConfig.fromOtherAndConfiguration(
230:                         original.priorityQueueConfig, config);
231: 
232:         // configure local directories
233:         if (original.localForStDirectories != null) {
234:             this.localForStDirectories = original.localForStDirectories;
235:         } else {
236:             final String forStLocalPaths = config.get(ForStOptions.LOCAL_DIRECTORIES);
237:             if (forStLocalPaths != null) {
238:                 String[] directories = forStLocalPaths.split(",|" + File.pathSeparator);
239: 
240:                 try {
241:                     setLocalDbStoragePaths(directories);
242:                 } catch (IllegalArgumentException e) {
243:                     throw new IllegalConfigurationException(
244:                             "Invalid configuration for ForSt state "
245:                                     + "backend's local storage directories: "
246:                                     + e.getMessage(),
247:                             e);
248:                 }
249:             }
250:         }
251: 
252:         // configure metric options
253:         this.nativeMetricOptions = ForStNativeMetricOptions.fromConfig(config);
254: 
255:         // configurable options
256:         this.configurableOptions = mergeConfigurableOptions(original.configurableOptions, config);
257: 
258:         // configure ForSt options factory
259:         try {
260:             forStOptionsFactory =
261:                     configureOptionsFactory(
262:                             original.forStOptionsFactory,
263:                             config.get(ForStOptions.OPTIONS_FACTORY),
264:                             config,
265:                             classLoader);
266:         } catch (DynamicCodeLoadingException e) {
267:             throw new FlinkRuntimeException(e);
268:         }
269: 
270:         // configure latency tracking
271:         latencyTrackingConfigBuilder = original.latencyTrackingConfigBuilder.configure(config);
272: 
273:         this.forStMemoryFactory = original.forStMemoryFactory;
274: 
275:         // configure overlap fraction threshold
276:         overlapFractionThreshold =
277:                 original.overlapFractionThreshold == UNDEFINED_OVERLAP_FRACTION_THRESHOLD
278:                         ? config.get(RESTORE_OVERLAP_FRACTION_THRESHOLD)
279:                         : original.overlapFractionThreshold;
280: 
281:         checkArgument(
282:                 overlapFractionThreshold >= 0 && this.overlapFractionThreshold <= 1,
283:                 "Overlap fraction threshold of restoring should be between 0 and 1");
284: 
285:         useIngestDbRestoreMode =
286:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
287:                         original.useIngestDbRestoreMode, USE_INGEST_DB_RESTORE_MODE, config);
288: 
289:         rescalingUseDeleteFilesInRange =
290:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
291:                         original.rescalingUseDeleteFilesInRange,
292:                         USE_DELETE_FILES_IN_RANGE_DURING_RESCALING,
293:                         config);
294: 
295:         if (config.getOptional(RESTORE_MODE).isPresent()) {
296:             recoveryClaimMode = config.get(RESTORE_MODE);
297:         }
298:     }
299: 
300:     // ------------------------------------------------------------------------
301:     //  Reconfiguration
302:     // ------------------------------------------------------------------------
303: 
304:     /**
305:      * Creates a copy of this state backend that uses the values defined in the configuration for
306:      * fields where that were not yet specified in this state backend.
307:      *
308:      * @param config The configuration.
309:      * @param classLoader The class loader.
310:      * @return The re-configured variant of the state backend
311:      */
312:     @Override
313:     public ForStStateBackend configure(ReadableConfig config, ClassLoader classLoader) {
314:         return new ForStStateBackend(this, config, classLoader);
315:     }
