383:     @Override
384:     public <K> ForStKeyedStateBackend<K> createAsyncKeyedStateBackend(
385:             KeyedStateBackendParameters<K> parameters) throws IOException {
386:         Environment env = parameters.getEnv();
387: 
388:         // first, make sure that the ForSt JNI library is loaded
389:         // we do this explicitly here to have better error handling
390:         String tempDir = env.getTaskManagerInfo().getTmpWorkingDirectory().getAbsolutePath();
391:         ensureForStIsLoaded(tempDir, env.getAsyncOperationsThreadPool());
392: 
393:         // replace all characters that are not legal for filenames with underscore
394:         String fileCompatibleIdentifier =
395:                 parameters.getOperatorIdentifier().replaceAll("[^a-zA-Z0-9\\-]", "_");
396: 
397:         lazyInitializeForJob(env, fileCompatibleIdentifier);
398: 
399:         String opChildPath =
400:                 String.format(
401:                         "op_%s_attempt_%s",
402:                         fileCompatibleIdentifier, env.getTaskInfo().getAttemptNumber());
403: 
404:         Path localBasePath =
405:                 new Path(
406:                         new File(new File(getNextStoragePath(), jobId.toHexString()), opChildPath)
407:                                 .getAbsolutePath());
408:         Path remoteBasePath = null;
409:         if (remoteForStDirectory != null) {
410:             remoteBasePath =
411:                     new Path(new Path(remoteForStDirectory, jobId.toHexString()), opChildPath);
412:         } else if (primaryShareWithCheckpoint) {
413:             if (env.getCheckpointStorageAccess() instanceof FsCheckpointStorageAccess) {
414:                 Path sharedStateDirectory =
415:                         ((FsCheckpointStorageAccess) env.getCheckpointStorageAccess())
416:                                 .getSharedStateDirectory();
417:                 remoteBasePath = new Path(sharedStateDirectory, opChildPath);
418:                 LOG.info("Set remote ForSt directory to checkpoint directory {}", remoteBasePath);
419:             } else {
420:                 LOG.warn(
421:                         "Remote ForSt directory can't be set, because checkpoint directory isn't on file system.");
422:             }
423:         }
424: 
425:         final OpaqueMemoryResource<ForStSharedResources> sharedResources =
426:                 ForStOperationUtils.allocateSharedCachesIfConfigured(
427:                         memoryConfiguration,
428:                         env,
429:                         parameters.getManagedMemoryFraction(),
430:                         LOG,
431:                         forStMemoryFactory);
432:         if (sharedResources != null) {
433:             LOG.info("Obtained shared ForSt cache of size {} bytes", sharedResources.getSize());
434:         }
435:         final ForStResourceContainer resourceContainer =
436:                 createOptionsAndResourceContainer(
437:                         sharedResources,
438:                         localBasePath,
439:                         remoteBasePath,
440:                         env.getCheckpointStorageAccess(),
441:                         parameters.getMetricGroup(),
442:                         nativeMetricOptions.isStatisticsEnabled());
443: 
444:         ForStKeyedStateBackendBuilder<K> builder =
445:                 new ForStKeyedStateBackendBuilder<>(
446:                                 parameters.getOperatorIdentifier(),
447:                                 env.getUserCodeClassLoader().asClassLoader(),
448:                                 resourceContainer,
449:                                 stateName -> resourceContainer.getColumnOptions(),
450:                                 parameters.getKeySerializer(),
451:                                 parameters.getNumberOfKeyGroups(),
452:                                 parameters.getKeyGroupRange(),
453:                                 env.getExecutionConfig(),
454:                                 priorityQueueConfig,
455:                                 parameters.getTtlTimeProvider(),
456:                                 parameters.getMetricGroup(),
457:                                 parameters.getCustomInitializationMetrics(),
458:                                 parameters.getStateHandles(),
459:                                 parameters.getCancelStreamRegistry())
460:                         // TODO: remove after support more snapshot strategy
461:                         .setEnableIncrementalCheckpointing(true)
462:                         .setNativeMetricOptions(
463:                                 resourceContainer.getMemoryWatcherOptions(nativeMetricOptions))
464:                         .setOverlapFractionThreshold(
465:                                 overlapFractionThreshold == UNDEFINED_OVERLAP_FRACTION_THRESHOLD
466:                                         ? RESTORE_OVERLAP_FRACTION_THRESHOLD.defaultValue()
467:                                         : overlapFractionThreshold)
468:                         .setUseIngestDbRestoreMode(
469:                                 useIngestDbRestoreMode.getOrDefault(
470:                                         USE_INGEST_DB_RESTORE_MODE.defaultValue()))
471:                         .setRescalingUseDeleteFilesInRange(
472:                                 rescalingUseDeleteFilesInRange.getOrDefault(
473:                                         USE_DELETE_FILES_IN_RANGE_DURING_RESCALING.defaultValue()))
474:                         .setRecoveryClaimMode(recoveryClaimMode);
475: 
476:         return builder.build();
477:     }
