545:                                 parameters.getKeyGroupRange(),
546:                                 executionConfig,
547:                                 localRecoveryConfig,
548:                                 priorityQueueConfig,
549:                                 parameters.getTtlTimeProvider(),
550:                                 latencyTrackingStateConfig,
551:                                 parameters.getMetricGroup(),
552:                                 parameters.getCustomInitializationMetrics(),
553:                                 parameters.getStateHandles(),
554:                                 keyGroupCompressionDecorator,
555:                                 parameters.getCancelStreamRegistry())
556:                         .setNativeMetricOptions(
557:                                 resourceContainer.getMemoryWatcherOptions(nativeMetricOptions))
558:                         .setOverlapFractionThreshold(
559:                                 overlapFractionThreshold == UNDEFINED_OVERLAP_FRACTION_THRESHOLD
560:                                         ? RESTORE_OVERLAP_FRACTION_THRESHOLD.defaultValue()
561:                                         : overlapFractionThreshold)
562:                         .setUseIngestDbRestoreMode(
563:                                 useIngestDbRestoreMode.getOrDefault(
