538:         final Collection<JobStatusListener> tmpJobStatusListeners = new ArrayList<>();
539:         tmpJobStatusListeners.add(Preconditions.checkNotNull(jobStatusListener));
540:         tmpJobStatusListeners.add(jobStatusStore);
541: 
542:         final MetricOptions.JobStatusMetricsSettings jobStatusMetricsSettings =
543:                 MetricOptions.JobStatusMetricsSettings.fromConfiguration(configuration);
544: 
545:         deploymentTimeMetrics =
546:                 new DeploymentStateTimeMetrics(jobGraph.getJobType(), jobStatusMetricsSettings);
547: 
548:         SchedulerBase.registerJobMetrics(
549:                 jobManagerJobMetricGroup,
550:                 jobStatusStore,
551:                 () -> (long) numRestarts,
552:                 deploymentTimeMetrics,
553:                 tmpJobStatusListeners::add,
554:                 initializationTimestamp,
555:                 jobStatusMetricsSettings);
556: 
557:         jobStatusListeners = Collections.unmodifiableCollection(tmpJobStatusListeners);
558:         this.failureEnrichers = failureEnrichers;
559:         this.exceptionHistory =
560:                 new BoundedFIFOQueue<>(configuration.get(WebOptions.MAX_EXCEPTION_HISTORY_SIZE));
561:         this.jobManagerJobMetricGroup = jobManagerJobMetricGroup;
562: 
563:         this.jobFailureMetricReporter = new JobFailureMetricReporter(jobManagerJobMetricGroup);
564:         this.reportEventsAsSpans = configuration.get(TraceOptions.REPORT_EVENTS_AS_SPANS);
565:     }
