357:         final Spliterator<REPORTER_FACTORY> factoryIteratorSPI =
358:                 ServiceLoader.load(reporterSetupInfo.factoryTypeClass).spliterator();
359:         final Spliterator<REPORTER_FACTORY> factoryIteratorPlugins =
