85:     /** Builder for metric reporter. */
86:     public static final ReporterSetupBuilder<MetricReporter, ReporterSetup, MetricReporterFactory>
87:             METRIC_SETUP_BUILDER =
88:                     new ReporterSetupBuilder<>(
89:                             new ReporterSetupInfo<>(
90:                                     MetricReporter.class,
91:                                     MetricReporterFactory.class,
