93:                                     MetricOptions.REPORTER_FACTORY_CLASS,
94:                                     MetricOptions.REPORTERS_LIST,
95:                                     MetricOptions.REPORTER_ADDITIONAL_VARIABLES,
96:                                     createReporterClassPattern(
97:                                             Pattern.quote(ConfigConstants.METRICS_REPORTER_PREFIX),
98:                                             '('
99:                                                     + Pattern.quote(
100:                                                             MetricOptions.REPORTER_FACTORY_CLASS
101:                                                                     .key())
102:                                                     + ')'),
103:                                     LIST_PATTERN,
104:                                     MetricReporterFactory::createMetricReporter,
105:                                     ReporterSetup::new));
106: 
107:     /** Builder for span/trace reporter. */
108:     public static final ReporterSetupBuilder<
109:                     TraceReporter, TraceReporterSetup, TraceReporterFactory>
110:             TRACE_SETUP_BUILDER =
111:                     new ReporterSetupBuilder<>(
112:                             new ReporterSetupInfo<>(
113:                                     TraceReporter.class,
114:                                     TraceReporterFactory.class,
115:                                     ConfigConstants.EVENTS_REPORTER_PREFIX,
116:                                     TraceOptions.REPORTER_FACTORY_CLASS,
117:                                     TraceOptions.TRACE_REPORTERS_LIST,
118:                                     TraceOptions.REPORTER_ADDITIONAL_VARIABLES,
119:                                     createReporterClassPattern(
120:                                             Pattern.quote(ConfigConstants.TRACES_REPORTER_PREFIX),
121:                                             Pattern.quote(
122:                                                     TraceOptions.REPORTER_FACTORY_CLASS.key())),
123:                                     LIST_PATTERN,
124:                                     TraceReporterFactory::createTraceReporter,
125:                                     (reporterName,
126:                                             metricConfig,
127:                                             traceReporter,
128:                                      reporterFilter,
129:                                             additionalVariables) ->
130:                                             new TraceReporterSetup(
131:                                                     reporterName,
132:                                                     metricConfig,
133:                                                     traceReporter,
134:                                                     additionalVariables)));
