136:     /**
137:      * Functional interface to unify access to different reporter factories that don't have a proper
138:      * superclass.
139:      *
140:      * @param <REPORTER_FACTORY> type of the reporter factory.
141:      * @param <REPORTER> type of the reporter.
142:      */
143:     @FunctionalInterface
144:     interface ReporterFactoryAdapter<REPORTER_FACTORY, REPORTER> {
145:         REPORTER invoke(REPORTER_FACTORY factory, MetricConfig metricConfig);
146:     }
