148:     /**
149:      * Factory interface to create the desired type of reporter setup.
150:      *
151:      * @param <SETUP> type of the created setup.
152:      * @param <REPORTER> type of the reporter.
153:      */
154:     interface ReporterSetupFactory<SETUP, REPORTER> {
155:         SETUP createReporterSetup(
156:                 String reporterName,
157:                 MetricConfig metricConfig,
158:                 REPORTER reporter,
159:                 MetricFilter reporterFilter,
160:                 Map<String, String> additionalVariables);
