163:     /**
164:      * Helper class that bundles all the information for a reporter type together so that we can
165:      * handle all types in generic code.
166:      *
167:      * @param <REPORTER> type of the reporter.
168:      * @param <SETUP> type of the setup.
169:      * @param <REPORTER_FACTORY> type of the reporter factory.
170:      */
171:     static class ReporterSetupInfo<
172:             REPORTER extends Reporter,
173:             SETUP extends AbstractReporterSetup<REPORTER>,
174:             REPORTER_FACTORY> {
175:         ReporterSetupInfo(
176:                 Class<REPORTER> reporterTypeClass,
177:                 Class<REPORTER_FACTORY> factoryTypeClass,
178:                 String reporterPrefix,
179:                 ConfigOption<String> factoryClassConfig,
180:                 ConfigOption<String> reportersList,
181:                 ConfigOption<Map<String, String>> reporterAdditionalVariables,
182:                 Pattern reporterClassPattern,
183:                 Pattern reporterListPattern,
184:                 ReporterFactoryAdapter<REPORTER_FACTORY, REPORTER> reporterFactoryAdapter,
185:                 ReporterSetupFactory<SETUP, REPORTER> reporterSetupFactory) {
186:             this.reporterTypeClass = reporterTypeClass;
187:             this.factoryTypeClass = factoryTypeClass;
188:             this.reporterPrefix = reporterPrefix;
189:             this.factoryClassConfig = factoryClassConfig;
190:             this.reportersList = reportersList;
191:             this.reporterAdditionalVariables = reporterAdditionalVariables;
192:             this.reporterClassPattern = reporterClassPattern;
193:             this.reporterListPattern = reporterListPattern;
194:             this.reporterFactoryAdapter = reporterFactoryAdapter;
195:             this.reporterSetupFactory = reporterSetupFactory;
196:         }
