198:         /** Class of the reporter. */
199:         Class<REPORTER> reporterTypeClass;
200: 
201:         /** Class of the reporter factory. */
202:         Class<REPORTER_FACTORY> factoryTypeClass;
203: 
204:         /**
205:          * Package prefix for the reporter class. Taken from {@link ConfigConstants}, e.g. {@link
206:          * ConfigConstants#METRICS_REPORTER_PREFIX}.
207:          */
208:         String reporterPrefix;
