91: 
92:     @Override
93:     public List<Expression> apply(List<Expression> expression, ResolutionContext context) {
94:         // only the top-level expressions may access the output data type
95:         final SurroundingInfo surroundingInfo =
96:                 context.getOutputDataType().map(SurroundingInfo::of).orElse(null);
97:         return expression.stream()
98:                 .flatMap(e -> e.accept(new ResolvingCallVisitor(context, surroundingInfo)).stream())
99:                 .collect(Collectors.toList());
