173:         @Override
174:         protected List<ResolvedExpression> defaultMethod(Expression expression) {
175:             if (expression instanceof ResolvedExpression) {
176:                 return Collections.singletonList((ResolvedExpression) expression);
177:             }
178:             throw new TableException("Unexpected unresolved expression: " + expression);
179:         }
