47: /**
48:  * (De)serializer for checkpoint metadata format version 3. This format was introduced with Apache
49:  * Flink 1.11.0.
50:  *
51:  * <p>Compared to format version 2, this drops some unused fields and introduces operator
52:  * coordinator state.
53:  *
54:  * <p>See {@link MetadataV2V3SerializerBase} for a description of the format layout.
55:  */
56: @Internal
57: public class MetadataV3Serializer extends MetadataV2V3SerializerBase implements MetadataSerializer {
58: 
59:     /** The metadata format version. */
60:     public static final int VERSION = 3;
61: 
62:     /** The singleton instance of the serializer. */
63:     public static final MetadataV3Serializer INSTANCE = new MetadataV3Serializer();
64: 
65:     private final ChannelStateHandleSerializer channelStateHandleSerializer =
66:             new ChannelStateHandleSerializer();
67: 
68:     /** Singleton, not meant to be instantiated. */
69:     protected MetadataV3Serializer() {}
70: 
71:     @Override
72:     public int getVersion() {
73:         return VERSION;
74:     }
75: 
76:     // ------------------------------------------------------------------------
77:     //  (De)serialization entry points
78:     // ------------------------------------------------------------------------
79: 
80:     @Override
81:     public void serialize(CheckpointMetadata checkpointMetadata, DataOutputStream dos)
82:             throws IOException {
83:         serializeMetadata(checkpointMetadata, dos);
84:     }
85: 
86:     @Override
87:     public CheckpointMetadata deserialize(
88:             DataInputStream dis, ClassLoader classLoader, String externalPointer)
89:             throws IOException {
90:         return deserializeMetadata(dis, externalPointer);
91:     }
92: 
93:     // ------------------------------------------------------------------------
94:     //  version-specific serialization formats
95:     // ------------------------------------------------------------------------
96: 
97:     @Override
98:     protected void serializeOperatorState(OperatorState operatorState, DataOutputStream dos)
99:             throws IOException {
100:         // Operator ID
101:         dos.writeLong(operatorState.getOperatorID().getLowerPart());
102:         dos.writeLong(operatorState.getOperatorID().getUpperPart());
103: 
104:         // Parallelism
105:         dos.writeInt(operatorState.getParallelism());
106:         dos.writeInt(operatorState.getMaxParallelism());
107: 
108:         // Coordinator state
109:         serializeStreamStateHandle(operatorState.getCoordinatorState(), dos);
110: 
111:         // Sub task states
112:         if (operatorState.isFullyFinished()) {
113:             dos.writeInt(-1);
114:         } else {
115:             final Map<Integer, OperatorSubtaskState> subtaskStateMap =
116:                     operatorState.getSubtaskStates();
117:             dos.writeInt(subtaskStateMap.size());
118:             for (Map.Entry<Integer, OperatorSubtaskState> entry : subtaskStateMap.entrySet()) {
119:                 boolean isFinished = entry.getValue().isFinished();
120:                 serializeSubtaskIndexAndFinishedState(entry.getKey(), isFinished, dos);
121:                 if (!isFinished) {
122:                     serializeSubtaskState(entry.getValue(), dos);
123:                 }
124:             }
125:         }
126:     }
127: 
128:     private void serializeSubtaskIndexAndFinishedState(
129:             int subtaskIndex, boolean isFinished, DataOutputStream dos) throws IOException {
130:         if (isFinished) {
131:             // We store a negative index for the finished subtask. In consideration
132:             // of the index 0, the negative index would start from -1.
133:             dos.writeInt(-(subtaskIndex + 1));
134:         } else {
135:             dos.writeInt(subtaskIndex);
136:         }
137:     }
138: 
139:     @Override
140:     protected void serializeSubtaskState(OperatorSubtaskState subtaskState, DataOutputStream dos)
141:             throws IOException {
142:         super.serializeSubtaskState(subtaskState, dos);
143:         serializeCollection(
144:                 subtaskState.getInputChannelState(), dos, this::serializeInputChannelStateHandle);
145:         serializeCollection(
146:                 subtaskState.getResultSubpartitionState(),
147:                 dos,
148:                 this::serializeResultSubpartitionStateHandle);
149:     }
150: 
151:     @Override
152:     protected OperatorState deserializeOperatorState(
153:             DataInputStream dis, @Nullable DeserializationContext context) throws IOException {
154:         final OperatorID jobVertexId = new OperatorID(dis.readLong(), dis.readLong());
155:         final int parallelism = dis.readInt();
156:         final int maxParallelism = dis.readInt();
157: 
158:         ByteStreamStateHandle coordinateState =
159:                 deserializeAndCheckByteStreamStateHandle(dis, context);
160: 
161:         final int numSubTaskStates = dis.readInt();
162:         if (numSubTaskStates < 0) {
163:             checkState(
164:                     coordinateState == null,
165:                     "Coordinator State should be null for fully finished operator state");
166:             return new FullyFinishedOperatorState(
167:                     null, null, jobVertexId, parallelism, maxParallelism);
168:         }
169: 
170:         final OperatorState operatorState =
171:                 new OperatorState(null, null, jobVertexId, parallelism, maxParallelism);
172: 
173:         // Coordinator state
174:         operatorState.setCoordinatorState(coordinateState);
175: 
176:         // Sub task states
177:         for (int j = 0; j < numSubTaskStates; j++) {
178:             SubtaskAndFinishedState subtaskAndFinishedState =
179:                     deserializeSubtaskIndexAndFinishedState(dis);
180:             if (subtaskAndFinishedState.isFinished) {
181:                 operatorState.putState(
182:                         subtaskAndFinishedState.subtaskIndex,
183:                         FinishedOperatorSubtaskState.INSTANCE);
184:             } else {
185:                 final OperatorSubtaskState subtaskState = deserializeSubtaskState(dis, context);
186:                 operatorState.putState(subtaskAndFinishedState.subtaskIndex, subtaskState);
187:             }
188:         }
189: 
190:         return operatorState;
191:     }
192: 
193:     protected SubtaskAndFinishedState deserializeSubtaskIndexAndFinishedState(DataInputStream dis)
194:             throws IOException {
195:         int storedSubtaskIndex = dis.readInt();
196:         if (storedSubtaskIndex < 0) {
197:             return new SubtaskAndFinishedState(-storedSubtaskIndex - 1, true);
198:         } else {
199:             return new SubtaskAndFinishedState(storedSubtaskIndex, false);
200:         }
201:     }
202: 
