258:     @VisibleForTesting
259:     public static void serializeStreamStateHandle(
260:             StreamStateHandle stateHandle, DataOutputStream dos) throws IOException {
261:         MetadataV2V3SerializerBase.serializeStreamStateHandle(stateHandle, dos);
262:     }
