283:     public static void serializeKeyedStateHandleUtil(
284:             KeyedStateHandle stateHandle, DataOutputStream dos) throws IOException {
285:         INSTANCE.serializeKeyedStateHandle(stateHandle, dos);
286:     }
287: 
288:     @VisibleForTesting
289:     public static KeyedStateHandle deserializeKeyedStateHandleUtil(DataInputStream dis)
290:             throws IOException {
291:         return INSTANCE.deserializeKeyedStateHandle(dis, null);
292:     }
293: 
294:     @VisibleForTesting
295:     public static StateObjectCollection<InputStateHandle> deserializeInputChannelStateHandle(
296:             DataInputStream dis) throws IOException {
297:         return INSTANCE.deserializeInputChannelStateHandle(dis, null);
298:     }
299: 
300:     @VisibleForTesting
301:     public StateObjectCollection<OutputStateHandle> deserializeResultSubpartitionStateHandle(
302:             DataInputStream dis) throws IOException {
303:         return INSTANCE.deserializeResultSubpartitionStateHandle(dis, null);
304:     }
