306:     static class SubtaskAndFinishedState {
307: 
308:         final int subtaskIndex;
309: 
310:         final boolean isFinished;
311: 
312:         public SubtaskAndFinishedState(int subtaskIndex, boolean isFinished) {
313:             this.subtaskIndex = subtaskIndex;
314:             this.isFinished = isFinished;
315:         }
316:     }
