80:     /**
81:      * Returns a reference to the {@link FileSystem} instance for accessing the file system
82:      * identified by the given {@link URI}.
83:      *
84:      * @param uri the {@link URI} identifying the file system.
85:      * @return a reference to the {@link FileSystem} instance for accessing the file system
86:      *     identified by the given {@link URI}.
87:      * @throws IOException thrown if a reference to the file system instance could not be obtained.
88:      */
89:     public static ForStFlinkFileSystem get(URI uri) throws IOException {
90:         return new ForStFlinkFileSystem(
91:                 FileSystem.get(uri), uri.toString(), System.getProperty("java.io.tmpdir"), null);
92:     }
93: 
94:     public static ForStFlinkFileSystem get(URI uri, Path localBase, FileBasedCache fileBasedCache)
95:             throws IOException {
96:         Preconditions.checkNotNull(localBase, "localBase is null, remote uri: %s.", uri);
97:         return new ForStFlinkFileSystem(
98:                 FileSystem.get(uri), uri.toString(), localBase.toString(), fileBasedCache);
99:     }
