144:     @Override
145:     public synchronized ByteBufferWritableFSDataOutputStream create(
146:             Path path, WriteMode overwriteMode) throws IOException {
147:         FileMappingManager.RealPath mappingEntry = fileMappingManager.createFile(path);
148:         if (mappingEntry.isLocal) {
149:             return new ByteBufferWritableFSDataOutputStream(
150:                     localFS.create(mappingEntry.path, overwriteMode));
151:         }
152: 
153:         FSDataOutputStream originalOutputStream = delegateFS.create(path, overwriteMode);
154:         CachedDataOutputStream cachedDataOutputStream =
155:                 fileBasedCache == null ? null : fileBasedCache.create(originalOutputStream, path);
156:         return new ByteBufferWritableFSDataOutputStream(
157:                 cachedDataOutputStream == null ? originalOutputStream : cachedDataOutputStream);
158:     }
