162:             throws IOException {
163:         FileMappingManager.RealPath mappingEntry = fileMappingManager.mappingEntry(path);
164:         Preconditions.checkNotNull(mappingEntry);
165:         if (mappingEntry.isLocal) {
166:             return new ByteBufferReadableFSDataInputStream(
167:                     () -> localFS.open(mappingEntry.path, bufferSize),
