169:                     localFS.getFileStatus(mappingEntry.path).getLen());
170:         }
171:         FileStatus fileStatus = checkNotNull(getFileStatus(mappingEntry.path));
172:         return new ByteBufferReadableFSDataInputStream(
173:                 () -> {
174:                     FSDataInputStream inputStream = delegateFS.open(mappingEntry.path, bufferSize);
175:                     CachedDataInputStream cachedDataInputStream =
176:                             fileBasedCache == null
177:                                     ? null
178:                                     : fileBasedCache.open(mappingEntry.path, inputStream);
179:                     return cachedDataInputStream == null ? inputStream : cachedDataInputStream;
180:                 },
181:                 DEFAULT_INPUT_STREAM_CAPACITY,
182:                 fileStatus.getLen());
183:     }
