229:     @Override
230:     public synchronized boolean exists(final Path f) throws IOException {
231:         FileMappingManager.RealPath mappingEntry = fileMappingManager.mappingEntry(f);
232:         if (mappingEntry == null) {
233:             return delegateFS.exists(f) && delegateFS.getFileStatus(f).isDir();
234:         }
235: 
236:         boolean status = false;
237:         if (mappingEntry.isLocal) {
238:             status |= localFS.exists(mappingEntry.path);
239:             if (!status) {
240:                 status = delegateFS.exists(f);
241:             }
242:         } else {
243:             status = delegateFS.exists(mappingEntry.path);
244:         }
245:         return status;
246:     }
