248:     @Override
249:     public synchronized FileStatus getFileStatus(Path path) throws IOException {
250:         FileMappingManager.RealPath realPath = fileMappingManager.mappingEntry(path);
251:         Preconditions.checkNotNull(realPath);
252:         if (realPath.isLocal) {
253:             return localFS.getFileStatus(realPath.path);
254:         }
255:         return delegateFS.getFileStatus(realPath.path);
256:     }
