259:     public synchronized BlockLocation[] getFileBlockLocations(FileStatus file, long start, long len)
260:             throws IOException {
261:         Path path = file.getPath();
262:         FileMappingManager.RealPath mappingEntry = fileMappingManager.mappingEntry(path);
263:         Preconditions.checkNotNull(mappingEntry);
264:         if (mappingEntry.isLocal) {
265:             FileStatus localFile = localFS.getFileStatus(mappingEntry.path);
266:             return localFS.getFileBlockLocations(localFile, start, len);
267:         }
268:         return delegateFS.getFileBlockLocations(file, start, len);
269:     }
