352:     private class OverwriteObjectsCross
353:             implements CrossFunction<
354:                     Tuple2<IntValue, IntValue>,
355:                     Tuple2<IntValue, IntValue>,
356:                     Tuple2<IntValue, IntValue>> {
357:         private Scrambler scrambler = new Scrambler(true);
358: 
359:         @Override
360:         public Tuple2<IntValue, IntValue> cross(
361:                 Tuple2<IntValue, IntValue> a, Tuple2<IntValue, IntValue> b) throws Exception {
362:             return scrambler.scramble(a, b);
363:         }
