111:     private void bootstrapState(StateBackend configuration, String savepointPath) throws Exception {
112:         StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
113:         env.setRuntimeMode(RuntimeExecutionMode.AUTOMATIC);
114: 
115:         StateBootstrapTransformation<Account> transformation =
116:                 OperatorTransformation.bootstrapWith(env.fromData(accounts))
117:                         .keyBy(acc -> acc.id)
118:                         .transform(new AccountBootstrapper());
119: 
120:         StateBootstrapTransformation<CurrencyRate> broadcastTransformation =
121:                 OperatorTransformation.bootstrapWith(env.fromData(currencyRates))
122:                         .transform(new CurrencyBootstrapFunction());
123: 
124:         SavepointWriter writer =
125:                 configuration == null
126:                         ? SavepointWriter.newSavepoint(env, 128)
127:                         : SavepointWriter.newSavepoint(env, configuration, 128);
128: 
129:         writer.withOperator(OperatorIdentifier.forUid(ACCOUNT_UID), transformation)
130:                 .withOperator(getUidHashFromUid(CURRENCY_UID), broadcastTransformation)
131:                 .write(savepointPath);
132: 
133:         env.execute("Bootstrap");
134:     }
