141:         }
142: 
143:         DataStream<Account> stream =
144:                 env.fromData(accounts)
145:                         .keyBy(acc -> acc.id)
146:                         .flatMap(new UpdateAndGetAccount())
147:                         .uid(ACCOUNT_UID);
148: 
149:         final CloseableIterator<Account> results = stream.collectAsync();
150: 
151:         env.fromData(currencyRates)
152:                 .connect(env.fromData(currencyRates).broadcast(descriptor))
153:                 .process(new CurrencyValidationFunction())
154:                 .uid(CURRENCY_UID)
155:                 .sinkTo(new DiscardingSink<>());
156: 
157:         final StreamGraph streamGraph = env.getStreamGraph();
158:         streamGraph.setSavepointRestoreSettings(
159:                 SavepointRestoreSettings.forPath(savepointPath, false));
160: 
161:         env.execute(streamGraph);
162: 
163:         assertThat(results).toIterable().hasSize(3);
164:         results.close();
165:     }
