828:                         })
829:                 .process(
830:                         new ProcessFunction<Tuple2<Integer, Long>, Object>() {
831:                             private static final long serialVersionUID = -805125545438296619L;
832: 
833:                             private transient MapState<Integer, Tuple2<Integer, Long>> mapState;
834: 
835:                             @Override
836:                             public void open(OpenContext openContext) throws Exception {
