654:     /**
655:      * Creates the parallelism store that should be used to build the {@link ExecutionGraph}, which
656:      * will respect the vertex parallelism of the passed {@link JobGraph} in all execution modes.
657:      *
658:      * @param jobGraph The job graph for execution.
659:      * @param executionMode The mode of scheduler execution.
660:      * @param defaultMaxParallelismFunc a function for computing a default max parallelism if none
661:      *     is specified on a given vertex
662:      * @return The parallelism store.
663:      */
664:     @VisibleForTesting
665:     static VertexParallelismStore computeVertexParallelismStoreForExecution(
666:             JobGraph jobGraph,
667:             SchedulerExecutionMode executionMode,
668:             Function<JobVertex, Integer> defaultMaxParallelismFunc) {
669:         if (executionMode == SchedulerExecutionMode.REACTIVE) {
670:             return computeReactiveModeVertexParallelismStore(
671:                     jobGraph.getVertices(), defaultMaxParallelismFunc, false);
672:         }
673:         return SchedulerBase.computeVertexParallelismStore(
674:                 jobGraph.getVertices(), defaultMaxParallelismFunc);
675:     }
