758:     private CompletableFuture<Map<String, String>> labelFailure(
759:             final TaskExecutionStateTransition taskExecutionStateTransition) {
760:         if (taskExecutionStateTransition.getExecutionState() == ExecutionState.FAILED
761:                 && !failureEnrichers.isEmpty()) {
762:             final Throwable cause = taskExecutionStateTransition.getError(userCodeClassLoader);
763:             final Context ctx =
764:                     DefaultFailureEnricherContext.forTaskFailure(
765:                             jobInfo, jobManagerJobMetricGroup, ioExecutor, userCodeClassLoader);
766:             return FailureEnricherUtils.labelFailure(
767:                     cause, ctx, getMainThreadExecutor(), failureEnrichers);
768:         }
769:         return FailureEnricherUtils.EMPTY_FAILURE_LABELS;
770:     }
