1080:     @VisibleForTesting
1081:     static boolean hasDesiredResources(
1082:             ResourceCounter desiredResources, Collection<? extends SlotInfo> freeSlots) {
1083:         ResourceCounter outstandingResources = desiredResources;
1084:         final Iterator<? extends SlotInfo> slotIterator = freeSlots.iterator();
1085: 
1086:         while (!outstandingResources.isEmpty() && slotIterator.hasNext()) {
1087:             final SlotInfo slotInfo = slotIterator.next();
1088:             final ResourceProfile resourceProfile = slotInfo.getResourceProfile();
1089: 
1090:             if (outstandingResources.containsResource(resourceProfile)) {
1091:                 outstandingResources = outstandingResources.subtract(resourceProfile, 1);
1092:             } else {
1093:                 outstandingResources = outstandingResources.subtract(ResourceProfile.UNKNOWN, 1);
1094:             }
1095:         }
1096: 
1097:         return outstandingResources.isEmpty();
1098:     }
