1558:     /**
1559:      * Check for slots that are idle for more than {@link JobManagerOptions#SLOT_IDLE_TIMEOUT} and
1560:      * release them back to the ResourceManager.
1561:      */
1562:     private void checkIdleSlotTimeout() {
1563:         if (getState().getJobStatus().isGloballyTerminalState()) {
1564:             // Job has reached the terminal state, so we can return all slots to the ResourceManager
1565:             // to speed things up because we no longer need them. This optimization lets us skip
1566:             // waiting for the slot pool service to close.
1567:             for (SlotInfo slotInfo : declarativeSlotPool.getAllSlotsInformation()) {
1568:                 declarativeSlotPool.releaseSlot(
1569:                         slotInfo.getAllocationId(),
1570:                         new FlinkException(
1571:                                 "Returning slots to their owners, because the job has reached a globally terminal state."));
1572:             }
1573:             return;
1574:         } else if (getState().getJobStatus().isTerminalState()) {
1575:             // do nothing
1576:             // prevent idleness check running again while scheduler was already shut down
1577:             // don't release slots because JobMaster may want to hold on to slots in case
1578:             // it re-acquires leadership
1579:             return;
1580:         }
1581:         declarativeSlotPool.releaseIdleSlots(System.currentTimeMillis());
1582:         getMainThreadExecutor()
1583:                 .schedule(
1584:                         this::checkIdleSlotTimeout,
1585:                         settings.getSlotIdleTimeout().toMillis(),
1586:                         TimeUnit.MILLISECONDS);
1587:     }
