1333:     @Override
1334:     public CreatingExecutionGraph.AssignmentResult tryToAssignSlots(
1335:             CreatingExecutionGraph.ExecutionGraphWithVertexParallelism
1336:                     executionGraphWithVertexParallelism) {
1337:         final ExecutionGraph executionGraph =
1338:                 executionGraphWithVertexParallelism.getExecutionGraph();
1339: 
1340:         executionGraph.start(componentMainThreadExecutor);
1341: 
1342:         executionGraph.setInternalTaskFailuresListener(
1343:                 new UpdateSchedulerNgOnInternalFailuresListener(this));
1344: 
1345:         final JobSchedulingPlan jobSchedulingPlan =
1346:                 executionGraphWithVertexParallelism.getJobSchedulingPlan();
1347:         return slotAllocator
1348:                 .tryReserveResources(jobSchedulingPlan)
1349:                 .map(reservedSlots -> assignSlotsToExecutionGraph(executionGraph, reservedSlots))
1350:                 .map(CreatingExecutionGraph.AssignmentResult::success)
1351:                 .orElseGet(CreatingExecutionGraph.AssignmentResult::notPossible);
1352:     }
1353: 
1354:     @Nonnull
1355:     private ExecutionGraph assignSlotsToExecutionGraph(
1356:             ExecutionGraph executionGraph, ReservedSlots reservedSlots) {
1357:         for (ExecutionVertex executionVertex : executionGraph.getAllExecutionVertices()) {
1358:             final LogicalSlot assignedSlot = reservedSlots.getSlotFor(executionVertex.getID());
1359:             final CompletableFuture<Void> registrationFuture =
1360:                     executionVertex
1361:                             .getCurrentExecutionAttempt()
1362:                             .registerProducedPartitions(assignedSlot.getTaskManagerLocation());
1363:             Preconditions.checkState(
1364:                     registrationFuture.isDone(),
1365:                     "Partition registration must be completed immediately for reactive mode");
1366: 
1367:             executionVertex.tryAssignResource(assignedSlot);
1368:         }
1369: 
1370:         return executionGraph;
1371:     }
