1430:     @Override
1431:     public FailureResult howToHandleFailure(
1432:             Throwable failure, CompletableFuture<Map<String, String>> failureLabels) {
1433:         FailureResult failureResult = howToHandleFailure(failure);
1434:         if (reportEventsAsSpans) {
1435:             // TODO: replace with reporting as event once events are supported.
1436:             // Add reporting as callback for when the failure labeling is completed.
1437:             failureLabels.thenAcceptAsync(
1438:                     (labels) -> jobFailureMetricReporter.reportJobFailure(failureResult, labels),
1439:                     componentMainThreadExecutor);
1440:         }
1441:         return failureResult;
1442:     }
1443: 
1444:     private FailureResult howToHandleFailure(Throwable failure) {
1445:         if (ExecutionFailureHandler.isUnrecoverableError(failure)) {
1446:             return FailureResult.canNotRestart(
1447:                     new JobException("The failure is not recoverable", failure));
1448:         }
1449: 
1450:         restartBackoffTimeStrategy.notifyFailure(failure);
1451:         if (restartBackoffTimeStrategy.canRestart()) {
1452:             return FailureResult.canRestart(
1453:                     failure, Duration.ofMillis(restartBackoffTimeStrategy.getBackoffTime()));
1454:         } else {
1455:             return FailureResult.canNotRestart(
1456:                     new JobException(
1457:                             "Recovery is suppressed by " + restartBackoffTimeStrategy, failure));
1458:         }
1459:     }
