+        this.jobID = jobID;
+        this.taskInfo = Preconditions.checkNotNull(taskInfo);
+        this.operatorID = Preconditions.checkNotNull(operatorID);
+        this.subtaskState = Preconditions.checkNotNull(subtaskState);
+    }
